"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('transfer-lab'))return;L.init(['rate','initial'],()=>{const a=L.range('rate'),y0=L.range('initial'),zi=t=>y0*Math.exp(-a*t),zs=t=>a===0?t:-Math.expm1(-a*t)/a,all=t=>zi(t)+zs(t),yMax=Math.max(1.2,all(4)*1.12,y0*1.12);L.plot(L.$('drawing'),[{fn:zi,color:'#cf604b'},{fn:zs,color:'#172a45',dash:'7 5'},{fn:all}],{xMax:4,yMin:0,yMax,yLabel:'輸出 y（無量綱）；三曲線共同縮放'});L.text('result-primary',L.fmt(all(1)));L.text('result-secondary','極點 s = '+L.fmt(-a)+' s⁻¹');L.text('feedback','完整輸出 = 零輸入 '+L.fmt(zi(1))+' + 零狀態 '+L.fmt(zs(1))+'（t=1 s）。H(s)=1/(s+a) 的單位是秒，因為輸入 u 的單位為 s⁻¹。'+(a>0?'極點在左半平面，初值項衰減；這個模型漸近穩定且 BIBO 穩定。':a===0?'a=0 是積分器，固定有界輸入仍讓 y 線性增長，因此不具 BIBO 穩定性。':'極點在右半平面，初值與輸入效果可指數增長，沒有會自行建立的正弦穩態。')+(y0===0?' 初值為零時，才可直接寫 Y=HU。':' 初值非零，必須加 y₀/(s+a)，不能只寫 Y=HU。'));});})();
